'use client'

import {useMemo, useState} from 'react'

type DuplicateFile = {
    fullPath: string
    relativePath: string
}

type DuplicateGroup = {
    hash: string
    files: DuplicateFile[]
}

function getRootFolder(relativePath: string) {
    return relativePath.split(/[\\/]/)[0]
}

function getFileName(relativePath: string) {
    return relativePath.split(/[\\/]/).pop() || relativePath
}

export default function Home() {
    const [duplicates, setDuplicates] = useState<DuplicateGroup[]>([])
    const [selected, setSelected] = useState<Record<string, DuplicateFile>>({})
    const [baseFolder, setBaseFolder] = useState<string | null>(null)
    const [loading, setLoading] = useState(false)

    // Per-group selected folder
    const [keepFolderMap, setKeepFolderMap] = useState<Record<string, string>>({})

    const scanFolder = async () => {
        const folder = await window.electronAPI.pickFolder()
        if (!folder) return

        setLoading(true)
        setBaseFolder(folder)
        setSelected({})
        setKeepFolderMap({})

        const result = await window.electronAPI.findDuplicates(folder)
        setDuplicates(result)

        setLoading(false)
    }

    // Get all unique top-level folders across all groups (A, B, C...)
    const allFolders = useMemo(() => {
        const set = new Set<string>()
        duplicates.forEach(group =>
            group.files.forEach(file =>
                set.add(getRootFolder(file.relativePath))
            )
        )
        return Array.from(set)
    }, [duplicates])

    const keepFromFolder = (group: DuplicateGroup, keepFolder: string) => {
        // Check if the selected folder actually has this file
        const keepFileExists = group.files.some(
            file => getRootFolder(file.relativePath) === keepFolder
        )

        // If B does NOT have this file (example: E.txt),
        // then do NOTHING for this group
        if (!keepFileExists) {
            return
        }

        // Mark UI selection
        setKeepFolderMap(prev => ({
            ...prev,
            [group.hash]: keepFolder
        }))

        // Select only duplicates OUTSIDE keepFolder
        setSelected(prev => {
            const updated = { ...prev }

            group.files.forEach(file => {
                const root = getRootFolder(file.relativePath)

                if (root !== keepFolder) {
                    updated[file.fullPath] = file
                } else {
                    delete updated[file.fullPath]
                }
            })

            return updated
        })
    }

    // ⭐ APPLY TO ALL
    const applyToAll = (keepFolder: string) => {
        const newSelected: Record<string, DuplicateFile> = {}
        const newKeepMap: Record<string, string> = {}

        duplicates.forEach(group => {
            // Only apply rule if keepFolder has this file
            const keepExists = group.files.some(
                file => getRootFolder(file.relativePath) === keepFolder
            )

            if (!keepExists) return

            newKeepMap[group.hash] = keepFolder

            group.files.forEach(file => {
                const root = getRootFolder(file.relativePath)
                if (root !== keepFolder) {
                    newSelected[file.fullPath] = file
                }
            })
        })

        setKeepFolderMap(newKeepMap)
        setSelected(newSelected)
    }

    const deleteSelected = async () => {
        if (!baseFolder) return

        const files = Object.values(selected)
        if (files.length === 0) return

        const confirmed = confirm(
            `Move ${files.length} files to recycle bin?`
        )
        if (!confirmed) return

        await window.electronAPI.deleteFiles(baseFolder, files)

        // Remove resolved groups
        setDuplicates(prev =>
            prev.filter(group =>
                group.files.some(f => !selected[f.fullPath])
            )
        )

        setSelected({})
        setKeepFolderMap({})
    }

    return (
        <main className="min-h-screen bg-gray-100 p-6">
            <div className="max-w-5xl mx-auto">

                {/* Header */}
                <header className="mb-6">
                    <h1 className="text-3xl font-bold text-gray-800">
                        Duplicate File Finder
                    </h1>
                    <p className="text-gray-600 mt-1">
                        Choose which folder to keep duplicates from
                    </p>
                </header>

                {/* Action Bar */}
                <div className="flex flex-wrap gap-4 mb-6">
                    <button
                        onClick={scanFolder}
                        disabled={loading}
                        className="px-6 py-2 rounded-lg bg-blue-600 text-white
                       hover:bg-blue-700 disabled:opacity-50"
                    >
                        {loading ? 'Scanning...' : 'Scan Folder'}
                    </button>

                    <button
                        onClick={deleteSelected}
                        disabled={Object.keys(selected).length === 0}
                        className="px-6 py-2 rounded-lg bg-red-600 text-white
                       hover:bg-red-700 disabled:opacity-50"
                    >
                        Move duplicates to recycle bin ({Object.keys(selected).length})
                    </button>
                </div>

                {/* ⭐ Apply to All */}
                {duplicates.length > 0 && allFolders.length > 1 && (
                    <div className="mb-6 bg-white border rounded-xl p-4 shadow-sm">
                        <p className="text-sm font-medium mb-3">
                            Apply to all duplicates:
                        </p>
                        <div className="flex gap-3 flex-wrap">
                            {allFolders.map(folder => (
                                <button
                                    key={folder}
                                    onClick={() => applyToAll(folder)}
                                    className="px-4 py-2 rounded-lg border text-sm font-medium
                             hover:bg-blue-50 hover:border-blue-400"
                                >
                                    Keep from {folder}
                                </button>
                            ))}
                        </div>
                    </div>
                )}

                {/* Empty State */}
                {!loading && duplicates.length === 0 && (
                    <div className="text-center text-gray-500 mt-20">
                        No duplicates found
                    </div>
                )}

                {/* Duplicate Groups */}
                <div className="space-y-4">
                    {duplicates.map(group => {
                        const folders = Array.from(
                            new Set(group.files.map(f =>
                                getRootFolder(f.relativePath)
                            ))
                        )

                        const fileName = getFileName(group.files[0].relativePath)
                        const selectedFolder = keepFolderMap[group.hash]

                        return (
                            <div
                                key={group.hash}
                                className="bg-white rounded-xl shadow border p-4"
                            >
                                <div className="flex items-center justify-between mb-3">
                                    <h2 className="text-lg font-semibold text-gray-800">
                                        {fileName}
                                    </h2>
                                    <span className="text-sm text-gray-500">
                    {group.files.length} copies
                  </span>
                                </div>

                                {folders.length > 1 && (
                                    <div className="flex gap-3 flex-wrap">
                                        {folders.map(folder => {
                                            const isSelected = selectedFolder === folder

                                            return (
                                                <button
                                                    key={folder}
                                                    onClick={() =>
                                                        keepFromFolder(group, folder)
                                                    }
                                                    className={`px-4 py-2 rounded-lg border text-sm font-medium
                            ${
                                                        isSelected
                                                            ? 'bg-blue-600 text-white border-blue-600'
                                                            : 'bg-white text-gray-700 hover:bg-blue-50 hover:border-blue-400'
                                                    }`}
                                                >
                                                    Keep from {folder}
                                                </button>
                                            )
                                        })}
                                    </div>
                                )}
                            </div>
                        )
                    })}
                </div>

            </div>
        </main>
    )
}
